pub fn git_diff_change_status_from_token(token: String) -> Rc<GitDiffChangeStatus> {
    {
        let letter = v1_rt::substring(&token, 0, 1);
let rest = v1_rt::substring(&token, 1, v1_rt::string_length(&token));
if (letter.clone() == "A".to_string()) {
            Rc::new(GitDiffChangeStatus::DiffAddedStatus)
        } else {
            if (letter.clone() == "D".to_string()) {
                Rc::new(GitDiffChangeStatus::DiffDeletedStatus)
            } else {
                if (letter.clone() == "M".to_string()) {
                    Rc::new(GitDiffChangeStatus::DiffModifiedStatus)
                } else {
                    if (letter.clone() == "T".to_string()) {
                        Rc::new(GitDiffChangeStatus::DiffTypeChangedStatus)
                    } else {
                        if (letter.clone() == "U".to_string()) {
                            Rc::new(GitDiffChangeStatus::DiffUnmergedStatus)
                        } else {
                            if (letter.clone() == "B".to_string()) {
                                Rc::new(GitDiffChangeStatus::DiffPairingBrokenStatus)
                            } else {
                                if (letter.clone() == "R".to_string()) {
                                    match v1_rt::parse_int(rest.clone()) {
    Some(score) => Rc::new(GitDiffChangeStatus::DiffRenamedStatus {
    similarity: crate::std_measure::percent(score.clone()),
}),
    std::option::Option::None => Rc::new(GitDiffChangeStatus::DiffUnknownGitStatus {
    raw: token.clone(),
}),
}
                                } else {
                                    if (letter.clone() == "C".to_string()) {
                                        match v1_rt::parse_int(rest.clone()) {
    Some(score) => Rc::new(GitDiffChangeStatus::DiffCopiedStatus {
    similarity: crate::std_measure::percent(score.clone()),
}),
    std::option::Option::None => Rc::new(GitDiffChangeStatus::DiffUnknownGitStatus {
    raw: token.clone(),
}),
}
                                    } else {
                                        Rc::new(GitDiffChangeStatus::DiffUnknownGitStatus {
    raw: token.clone(),
})
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
}
}

