pub fn git_dir_path_from_gitfile(contents: String) -> Option<String> {
    match Rc::new(contents.clone().split(&"\n".to_string()).map(|s| s.to_string()).collect::<Vec<_>>()).first().cloned() {
    std::option::Option::None => std::option::Option::None,
    Some(raw) => {
        let line = v1_rt::trim(raw.clone());
if !v1_rt::starts_with(line.clone(), git_dir_file_prefix()) {
            std::option::Option::None
        } else {
            {
                let rest = v1_rt::trim(v1_rt::substring(&line, v1_rt::string_length(&git_dir_file_prefix()), v1_rt::string_length(&line)));
if (rest.clone() == "".to_string()) {
                    std::option::Option::None
                } else {
                    Some(rest.clone())
                }
}
        }
},
}
}

pub fn resolve_git_dir_pointer(worktree: String, pointer: String) -> String {
    if v1_rt::starts_with(pointer.clone(), "/".to_string()) {
        pointer.clone()
    } else {
        Rc::new(vec![worktree.clone(), "/".to_string(), pointer.clone()]).join(&"".to_string())
    }
}

