pub type GitRemoteName = String;

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct GitRemoteUrlAt {
    pub repository_path: FilePath,
    pub name: GitRemoteName,
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct GitRemoteUrlMember {
    pub at: Rc<GitRemoteUrlAt>,
    pub url: NonEmptyStr,
}

pub fn git_remote_url_config_key(name: GitRemoteName) -> String {
    Rc::new(vec!["remote.".to_string(), name.clone(), ".url".to_string()]).join(&"".to_string())
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum GitRemoteUrlObservation {
    GitRemoteUrlObserved {
        member: Rc<GitRemoteUrlMember>,
    },
    GitRemoteUrlAbsent {
        at: Rc<GitRemoteUrlAt>,
    },
    GitRemoteUrlRepositoryUnusable {
        at: Rc<GitRemoteUrlAt>,
        exit_code: i64,
        stderr: String,
    },
    GitRemoteUrlReadRefused {
        at: Rc<GitRemoteUrlAt>,
        exit_code: i64,
        stderr: String,
    },
}

pub fn git_remote_get_url_no_such_remote_exit() -> i64 { 2 }

pub fn git_remote_get_url_not_a_repository_exit() -> i64 { 128 }

pub fn git_remote_url_observation_of(at: Rc<GitRemoteUrlAt>, exit_code: i64, stderr: String, url: String) -> Rc<GitRemoteUrlObservation> {
    if (exit_code.clone() == 0) {
        {
            let observed = v1_rt::trim(url.clone());
if (v1_rt::string_length(&observed) == 0) {
                Rc::new(GitRemoteUrlObservation::GitRemoteUrlReadRefused {
    at: at.clone(),
    exit_code: exit_code.clone(),
    stderr: stderr.clone(),
})
            } else {
                Rc::new(GitRemoteUrlObservation::GitRemoteUrlObserved {
    member: Rc::new(GitRemoteUrlMember {
    at: at.clone(),
    url: observed.clone(),
}),
})
            }
}
    } else {
        if (exit_code.clone() == git_remote_get_url_no_such_remote_exit()) {
            Rc::new(GitRemoteUrlObservation::GitRemoteUrlAbsent {
    at: at.clone(),
})
        } else {
            if (exit_code.clone() == git_remote_get_url_not_a_repository_exit()) {
                Rc::new(GitRemoteUrlObservation::GitRemoteUrlRepositoryUnusable {
    at: at.clone(),
    exit_code: exit_code.clone(),
    stderr: stderr.clone(),
})
            } else {
                Rc::new(GitRemoteUrlObservation::GitRemoteUrlReadRefused {
    at: at.clone(),
    exit_code: exit_code.clone(),
    stderr: stderr.clone(),
})
            }
        }
    }
}

pub fn git_ref_component_admitted(component: String) -> bool {
    ((((((((((((((v1_rt::string_length(&component) > 0) && !v1_rt::starts_with(component.clone(), ".".to_string())) && !v1_rt::string_contains(&component, "/".to_string())) && !v1_rt::string_contains(&component, "..".to_string())) && !v1_rt::string_contains(&component, " ".to_string())) && !v1_rt::string_contains(&component, "~".to_string())) && !v1_rt::string_contains(&component, "^".to_string())) && !v1_rt::string_contains(&component, ":".to_string())) && !v1_rt::string_contains(&component, "?".to_string())) && !v1_rt::string_contains(&component, "*".to_string())) && !v1_rt::string_contains(&component, "[".to_string())) && !v1_rt::string_contains(&component, "\\".to_string())) && !v1_rt::string_contains(&component, "@{".to_string())) && !v1_rt::ends_with(component.clone(), ".lock".to_string()))
}

